/* 2mm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "2mm.h"

/* --------------------------------------------------------------------
 * Tunable kernel parameters.
 *
 * T2MM_JBLOCK controls the blocking factor in the j-dimension (columns)
 * for both matrix multiplications. It should be chosen so that
 *   T2MM_JBLOCK * sizeof(DATA_TYPE)
 * fits comfortably in L1/L2 cache.
 * ------------------------------------------------------------------ */
#ifndef T2MM_JBLOCK
#  define T2MM_JBLOCK 64
#endif


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_2mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  /* NOTE:
   * We reorganize the computation to improve data locality and
   * enable efficient parallelization while preserving the numerical
   * behavior for each element:
   *
   *   1) Initialize tmp to zero in a separate pass.
   *   2) Compute tmp = alpha * A * B with loop order i-k-j so that
   *      the inner loop walks tmp[i][j] and B[k][j] with unit stride.
   *   3) Scale D by beta in a separate pass (independent of tmp).
   *   4) Compute D += tmp * C with loop order i-k-j so that the inner
   *      loop walks D[i][j] and C[k][j] with unit stride.
   *
   * For each (i,j) pair the sequence of floating-point operations
   * (order of k-accumulation and the single beta scaling) is the same
   * as in the original code; only the traversal order across different
   * (i,j) pairs is changed.
   */

#pragma scop
#pragma omp parallel
  {
    int i, j, k;

    /* 0. Initialize tmp to zero.
     *    Splitting this out allows a more cache-friendly and
     *    vectorizable structure in the matrix multiplication step.
     */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_NI; i++) {
      DATA_TYPE *tmp_row = &tmp[i][0];
      for (j = 0; j < _PB_NJ; j++)
        tmp_row[j] = SCALAR_VAL(0.0);
    }

    /* 1. tmp = alpha * A * B
     *
     * Loop order: i (outer) -> k -> j (inner).
     *  - j is the fastest-varying index (unit stride) for both
     *    tmp[i][j] and B[k][j], which improves cache utilization
     *    and enables vectorization.
     *  - We precompute a_ik = alpha * A[i][k] once per (i,k).
     *  - The j-dimension is blocked by T2MM_JBLOCK to improve
     *    L1/L2 locality for long rows.
     */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_NI; i++) {
      for (k = 0; k < _PB_NK; k++) {
        const DATA_TYPE a_ik = alpha * A[i][k];
        DATA_TYPE       *restrict tmp_row = &tmp[i][0];
        const DATA_TYPE *restrict B_row   = &B[k][0];

        for (int jj = 0; jj < _PB_NJ; jj += T2MM_JBLOCK) {
          const int j_end = (jj + T2MM_JBLOCK < _PB_NJ) ?
                            (jj + T2MM_JBLOCK) : _PB_NJ;

#pragma omp simd
          for (j = jj; j < j_end; j++) {
            tmp_row[j] += a_ik * B_row[j];
          }
        }
      }
    }

    /* 2. Scale D by beta.
     *
     * This step is independent of tmp and the matrix multiplications,
     * so it can also be parallelized over i.
     */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_NI; i++) {
      DATA_TYPE *D_row = &D[i][0];
      for (j = 0; j < _PB_NL; j++)
        D_row[j] *= beta;
    }

    /* 3. D += tmp * C
     *
     * Original computation:
     *   for each (i,j):
     *     D[i][j] *= beta;               -- already done above
     *     for k: D[i][j] += tmp[i][k]*C[k][j];
     *
     * Here we keep, for every (i,j), the same order of k-accumulation,
     * but use a cache-friendly traversal:
     *
     * Loop order: i (outer) -> k -> j (inner), and block j.
     */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_NI; i++) {
      DATA_TYPE *restrict D_row = &D[i][0];

      for (k = 0; k < _PB_NJ; k++) {
        const DATA_TYPE tmp_ik            = tmp[i][k];
        const DATA_TYPE *restrict C_row   = &C[k][0];

        for (int jj = 0; jj < _PB_NL; jj += T2MM_JBLOCK) {
          const int j_end = (jj + T2MM_JBLOCK < _PB_NL) ?
                            (jj + T2MM_JBLOCK) : _PB_NL;

#pragma omp simd
          for (j = jj; j < j_end; j++) {
            D_row[j] += tmp_ik * C_row[j];
          }
        }
      }
    }
  } /* end of parallel region */
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(tmp,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NJ,NL,nj,nl);
  POLYBENCH_2D_ARRAY_DECL(D,DATA_TYPE,NI,NL,ni,nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_2mm (ni, nj, nk, nl,
	      alpha, beta,
	      POLYBENCH_ARRAY(tmp),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(D)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);

  return 0;
}
