static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_2mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

  /* Create local restrict-qualified views of the input arrays.
   * This tells the compiler that these pointers do not alias,
   * which enables better vectorization and hoisting of loads.
   */
  DATA_TYPE (* restrict tmp_)[nj] = tmp;
  DATA_TYPE (* restrict A_)[nk]   = A;
  DATA_TYPE (* restrict B_)[nj]   = B;
  DATA_TYPE (* restrict C_)[nl]   = C;
  DATA_TYPE (* restrict D_)[nl]   = D;

#pragma scop
  /* D := alpha*A*B*C + beta*D
   *
   * The original implementation computed:
   *   tmp = alpha * A * B
   *   D   = beta * D + tmp * C
   *
   * Here we:
   *   1) Explicitly zero tmp.
   *   2) Use i-k-j loop ordering for both matrix multiplications
   *      so that the innermost loop iterates over the last index of
   *      each row-major array. This gives contiguous memory accesses
   *      for B, C, tmp, and D, greatly improving cache behavior.
   *   3) Hoist scalar invariants (e.g., alpha * A[i][k]) out of the
   *      innermost loop to reduce redundant arithmetic.
   *   4) Optionally exploit OpenMP parallelism across the outer i-loops
   *      (when compiled with -fopenmp). Each (i, j) element is updated
   *      by exactly one thread, so there are no data races.
   */

#pragma omp parallel if (_PB_NI >= 32) default(none) \
  private(i,j,k) \
  shared(tmp_,A_,B_,C_,D_,alpha,beta,ni,nj,nk,nl)
  {
    /* 1) Explicitly zero tmp.
     *    This replaces the per-element initialization that was previously
     *    folded into the first multiplication loop, and enables us to
     *    reorder that loop for better locality without changing results.
     */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_NI; i++)
      for (j = 0; j < _PB_NJ; j++)
        tmp_[i][j] = SCALAR_VAL(0.0);

    /* 2) Compute tmp = alpha * A * B.
     *
     * Loop order: i (outer), k (middle), j (inner)
     *
     * For each fixed (i, k):
     *   - A_[i][k] is read once and scaled by alpha.
     *   - The inner j-loop walks along row k of B and row i of tmp,
     *     both of which are contiguous in memory.
     *
     * For each element tmp[i][j], the accumulation over k is still
     * performed in increasing k order, exactly as in the original
     * implementation, so floating-point summation order is preserved.
     */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_NI; i++) {
      for (k = 0; k < _PB_NK; ++k) {
        DATA_TYPE a_ik = alpha * A_[i][k]; /* hoist invariant multiply */
        for (j = 0; j < _PB_NJ; ++j) {
          tmp_[i][j] += a_ik * B_[k][j];
        }
      }
    }

