     *
     * Loop order: i (outer), k (middle), j (inner)
     *
     * For each fixed (i, k):
     *   - tmp_[i][k] is loaded once.
     *   - The inner j-loop walks along row k of C and row i of D,
     *     again contiguous in memory for both arrays.
     *
     * For a fixed (i, j), the contributions from all k are still added
     * in increasing k order, same as in the original code, so the
     * floating-point reduction order is unchanged.
     */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_NI; i++) {
      for (k = 0; k < _PB_NJ; ++k) {
        DATA_TYPE tmp_ik = tmp_[i][k];
        for (j = 0; j < _PB_NL; ++j) {
          D_[i][j] += tmp_ik * C_[k][j];
        }
      }
    }
  } /* end OpenMP parallel region */

#pragma endscop

}


