   - Optional transposition of B and/or C into temporaries with
     cache-friendly layouts. This dramatically improves spatial
     locality for the innermost loops while keeping the arithmetic
     evaluation order for each element unchanged (no change in
     floating‑point summation order).
   - Use of temporary row pointers (A_row, tmp_row, D_row, etc.) to
     reduce address arithmetic and help the compiler vectorize.
   - OpenMP parallelization of the outer loops over 'i' (rows),
     which are fully independent. If the code is compiled without
     OpenMP support, the pragmas are ignored and execution remains
     sequential.
   - Accumulation in scalar temporaries for D (Dij), avoiding
     repeated loads/stores of D[i][j] in the inner loops while
     preserving the exact arithmetic sequence of the original code.
*/
static
void kernel_2mm [[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

  /* Local copies of loop bounds for clarity and to avoid repeated
     macro expansion of _PB_* in inner loops. */
  const int pb_ni = _PB_NI;
  const int pb_nj = _PB_NJ;
  const int pb_nk = _PB_NK;
  const int pb_nl = _PB_NL;

  /* Compute the original footprint in "element units" (not bytes).
     This is used to enforce the constraint that any extra temporary
     storage we allocate does not exceed 50% of the original program
     footprint. */
  const size_t orig_elems =
      (size_t)ni * (size_t)nk +
      (size_t)nk * (size_t)nj +
      (size_t)nj * (size_t)nl +
      (size_t)ni * (size_t)nl +
      (size_t)ni * (size_t)nj;

  const size_t add_B_elems = (size_t)nk * (size_t)nj; /* B^T: [nj][nk] */
  const size_t add_C_elems = (size_t)nj * (size_t)nl; /* C^T: [nl][nj] */
  const size_t max_extra   = orig_elems / 2;

  int use_Bt = 0;
  int use_Ct = 0;

  /* Decide which temporaries we are allowed to allocate given the
     50% memory overhead constraint. Preference is:
       1) both B^T and C^T, if they both fit,
       2) otherwise, the larger one that still fits (more benefit),
       3) otherwise, whichever fits,
       4) otherwise, none.
  */
  if (add_B_elems + add_C_elems <= max_extra) {
    use_Bt = 1;
    use_Ct = 1;
  } else if (add_B_elems <= max_extra && add_B_elems >= add_C_elems) {
    use_Bt = 1;
  } else if (add_C_elems <= max_extra) {
    use_Ct = 1;
  }

  /* Allocate and (if applicable) build transposed views. The
     transposed buffers are stored as 1D arrays with manual indexing:
       B_t[j * nk + k] = B[k][j]      (shape: [nj][nk])
       C_t[j * nj + k] = C[k][j]      (shape: [nl][nj])
  */
  DATA_TYPE *restrict B_t = NULL;
  DATA_TYPE *restrict C_t = NULL;

  if (use_Bt) {
    B_t = (DATA_TYPE *)
        polybench_alloc_data((unsigned long long)add_B_elems,
                             sizeof(DATA_TYPE));
    if (!B_t)
      use_Bt = 0; /* Allocation failed: fall back gracefully. */
  }

  if (use_Ct) {
    C_t = (DATA_TYPE *)
        polybench_alloc_data((unsigned long long)add_C_elems,
                             sizeof(DATA_TYPE));
    if (!C_t)
      use_Ct = 0; /* Allocation failed: fall back gracefully. */
  }

#pragma scop
  /* Build B^T if requested: B_t[j * nk + k] = B[k][j].
     Accesses:
       - Read B row-major (k is outer, j is inner => still contiguous
         in j for each k).
       - Write B_t row-major by j as outer index.
  */
  if (use_Bt) {
    const size_t stride_Bt = (size_t)nk;

    /* Parallelize the outer loop over k; each thread writes to
       disjoint regions of B_t. */
    #pragma omp parallel for private(j) schedule(static)
    for (k = 0; k < pb_nk; ++k) {
      for (j = 0; j < pb_nj; ++j) {
        B_t[(size_t)j * stride_Bt + (size_t)k] = B[k][j];
      }
    }
  }

  /* Build C^T if requested: C_t[j * nj + k] = C[k][j].
     Accesses:
       - Read original C row-major in its j dimension.
       - Write C_t row-major by j as outer index. */
  if (use_Ct) {
    const size_t stride_Ct = (size_t)nj;

    #pragma omp parallel for private(j) schedule(static)
    for (k = 0; k < pb_nj; ++k) {
      for (j = 0; j < pb_nl; ++j) {
