        DATA_TYPE sum = SCALAR_VAL(0.0);
        /* Inner loop: sum over k. Independent iterations,
           suitable for vectorization. */
        #pragma omp simd
        for (k = 0; k < pb_nk; ++k) {
          sum += alpha * A_row[k] * Bt_row[k];
        }
        tmp_row[j] = sum;
      }
    }
