       arithmetic and with OpenMP parallelization over 'i'. */
    #pragma omp parallel for private(j,k) schedule(static)
    for (i = 0; i < pb_ni; ++i) {
      DATA_TYPE *restrict tmp_row      = tmp[i];
      const DATA_TYPE *restrict A_row  = A[i];

      for (j = 0; j < pb_nj; ++j) {
        DATA_TYPE sum = SCALAR_VAL(0.0);
        #pragma omp simd
        for (k = 0; k < pb_nk; ++k) {
          sum += alpha * A_row[k] * B[k][j];
        }
        tmp_row[j] = sum;
      }
    }
  }

  /* ----------------------------------------------------------------
     Second phase: D = beta * D + tmp * C

       D[i][j] = beta * D[i][j] + sum_k tmp[i][k] * C[k][j]

     Again we preserve the arithmetic order per (i,j):
       - Initialize Dij = beta * D[i][j]
       - For k from 0 to nj-1: Dij += tmp[i][k] * C_elem
       - Store back D[i][j] = Dij

     The only change is whether we read C[k][j] directly or from
     its transposed view C_t[j][k].
     ---------------------------------------------------------------- */
  if (use_Ct) {
    const size_t stride_Ct = (size_t)nj;

    #pragma omp parallel for private(j,k) schedule(static)
    for (i = 0; i < pb_ni; ++i) {
      DATA_TYPE *restrict       D_row   = D[i];
      const DATA_TYPE *restrict tmp_row = tmp[i];

      for (j = 0; j < pb_nl; ++j) {
        const DATA_TYPE *restrict Ct_row =
            &C_t[(size_t)j * stride_Ct];

        /* Accumulator initialized exactly as in the original:
           Dij = beta * original_D. */
        DATA_TYPE Dij = beta * D_row[j];

        #pragma omp simd
        for (k = 0; k < pb_nj; ++k) {
          Dij += tmp_row[k] * Ct_row[k];
        }
        D_row[j] = Dij;
      }
    }
  } else {
    /* Baseline version with improved memory usage:
       accumulate in a scalar instead of repeatedly reading/writing
       D[i][j] in the inner loop. Floating-point addition order
       for Dij remains identical to the original. */
    #pragma omp parallel for private(j,k) schedule(static)
    for (i = 0; i < pb_ni; ++i) {
      DATA_TYPE *restrict       D_row   = D[i];
      const DATA_TYPE *restrict tmp_row = tmp[i];

      for (j = 0; j < pb_nl; ++j) {
        DATA_TYPE Dij = beta * D_row[j];

        #pragma omp simd
        for (k = 0; k < pb_nj; ++k) {
          Dij += tmp_row[k] * C[k][j];
        }
        D_row[j] = Dij;
      }
    }
  }
#pragma endscop

  /* Free temporaries if they were allocated. */
  free(B_t);
  free(C_t);
}


