static
void kernel_2mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  /* Create local restrict-qualified views of the matrices.
     This helps the compiler with alias analysis and vectorization. */
  DATA_TYPE (*restrict A_)[nk]   = A;
  DATA_TYPE (*restrict B_)[nj]   = B;
  DATA_TYPE (*restrict C_)[nl]   = C;
  DATA_TYPE (*restrict D_)[nl]   = D;
  DATA_TYPE (*restrict tmp_)[nj] = tmp;

#pragma scop
  /* D := alpha*A*B*C + beta*D
   *
   * We compute this as two blocked matrix multiplications:
   *   1) tmp  = alpha * A * B
   *   2) D    = beta * D + tmp * C
   *
   * Loop transformations:
   *   - j is the innermost index to maximize spatial locality.
   *   - Cache blocking (tiling) on i, j, k improves reuse.
   *   - OpenMP parallelization over i-tiles exploits multi-core CPUs.
   *
   * The mathematical result is identical to the original kernel; only
   * the evaluation order of floating-point operations changes.
