  for (int i = 0; i < _PB_NI; i++) {
    for (int j = 0; j < _PB_NJ; j++) {
      tmp_[i][j] = SCALAR_VAL(0.0);
    }
  }

  /* --------------------------------------------------------------------
   * Step 1: tmp = alpha * A * B
   *
   * Blocked GEMM:
   *   for ii (i-tiles)
   *     for kk (k-tiles)
   *       for jj (j-tiles)
   *         for i, k, j within the tile
   *
   * Inner-most loop updates contiguous segments of tmp and B,
   * enabling efficient cache use and SIMD vectorization.
   * ------------------------------------------------------------------ */
#pragma omp parallel for schedule(static)
  for (int ii = 0; ii < _PB_NI; ii += T2MM_TILE_I)
  {
    int i_end = ii + T2MM_TILE_I;
    if (i_end > _PB_NI)
      i_end = _PB_NI;

    for (int kk = 0; kk < _PB_NK; kk += T2MM_TILE_K)
    {
      int k_end = kk + T2MM_TILE_K;
      if (k_end > _PB_NK)
        k_end = _PB_NK;

      for (int jj = 0; jj < _PB_NJ; jj += T2MM_TILE_J)
      {
        int j_end = jj + T2MM_TILE_J;
