            DATA_TYPE *restrict tmp_row = &tmp_[i][jj];
            DATA_TYPE *restrict b_row   = &B_[k][jj];

            /* j loop: contiguous access, good for vectorization. */
            for (int jj_inner = 0; jj_inner < j_len; ++jj_inner)
            {
              tmp_row[jj_inner] += a_val * b_row[jj_inner];
            }
          }
        }
      }
    }
  }

  /* --------------------------------------------------------------------
   * Step 2: Scale D by beta.
   *
   * Separated from the accumulation step to keep the main GEMM-like
   * loops simple and to expose more ILP there.
   * ------------------------------------------------------------------ */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < _PB_NI; i++) {
    for (int j = 0; j < _PB_NL; j++) {
      D_[i][j] *= beta;
    }
  }

  /* --------------------------------------------------------------------
   * Step 3: D += tmp * C
   *
   * Another blocked GEMM:
   *   for ii (i-tiles)
   *     for kk (k-tiles over NJ)
   *       for jj (j-tiles over NL)
   *         update block of D
   *
   * Again, the innermost loop walks j contiguously.
   * ------------------------------------------------------------------ */
#pragma omp parallel for schedule(static)
  for (int ii = 0; ii < _PB_NI; ii += T2MM_TILE_I2)
  {
    int i_end = ii + T2MM_TILE_I2;
    if (i_end > _PB_NI)
      i_end = _PB_NI;

    for (int kk = 0; kk < _PB_NJ; kk += T2MM_TILE_K2)
    {
      int k_end = kk + T2MM_TILE_K2;
      if (k_end > _PB_NJ)
        k_end = _PB_NJ;

      for (int jj = 0; jj < _PB_NL; jj += T2MM_TILE_J2)
      {
        int j_end = jj + T2MM_TILE_J2;
        if (j_end > _PB_NL)
          j_end = _PB_NL;

        const int j_len = j_end - jj;

        for (int i = ii; i < i_end; ++i)
        {
          DATA_TYPE *restrict d_row = &D_[i][jj];

          for (int k = kk; k < k_end; ++k)
          {
            DATA_TYPE tmp_val = tmp_[i][k];
            const DATA_TYPE *restrict c_row = &C_[k][jj];

            for (int jj_inner = 0; jj_inner < j_len; ++jj_inner)
            {
              d_row[jj_inner] += tmp_val * c_row[jj_inner];
            }
          }
        }
      }
    }
  }
#pragma endscop

}


